16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub enum ItemType {
18	    Sword,
19	    Amulet,
20	    Staff,
21	    Potion,
22	    Rune,
23	    Moonstone,
24	}
25	
26	impl ItemType {
27	    /// Every item type the MHPCO insures. The office's vocabulary is exactly the
28	    /// names of these types, so listing them once is what lets `parse` accept a
29	    /// claimant's name and `name` cite it back without a second list to keep in
30	    /// step.
31	    const INSURED: [Self; 6] = [
32	        Self::Sword,
33	        Self::Amulet,
34	        Self::Staff,
35	        Self::Potion,
36	        Self::Rune,
37	        Self::Moonstone,
38	    ];
39	
40	    /// A component -- for example a rune or a moonstone -- rather than a main
41	    /// item. The MHPCO records no curse, enchantment or material for a
42	    /// component, and charges it per group of alike ones instead of giving it
43	    /// its own price-list row.
44	    fn is_component(self) -> bool {
45	        matches!(self, Self::Rune | Self::Moonstone)
46	    }
47	
48	    /// The MHPCO price-list row for a main item, or `None` for a component:
49	    /// components are not on the main price list, they are charged per group of
50	    /// alike ones by `component_charge`.
51	    fn main_item_base_premium(self) -> Option<f64> {
52	        match self {
53	            Self::Sword => Some(100.0),
54	            Self::Amulet => Some(60.0),
55	            Self::Staff => Some(80.0),
56	            Self::Potion => Some(40.0),
57	            Self::Rune | Self::Moonstone => None,
58	        }
59	    }
60	
61	    /// The MHPCO insures each item at its price-list insurance value. This is a
62	    /// separate price-list column from `main_item_base_premium`: the MHPCO reads
63	    /// the two independently, so a premium offer such as the component block
64	    /// discount moves one and leaves the other untouched.
65	    fn insurance_value(self) -> u64 {
66	        match self {
67	            Self::Sword => 1000,
68	            Self::Amulet => 600,
69	            Self::Staff => 800,
70	            Self::Potion => 400,
71	            Self::Rune | Self::Moonstone => COMPONENT_INSURANCE_VALUE,
72	        }
73	    }
74	
75	    /// What the MHPCO calls this item type -- the office's whole vocabulary,
76	    /// stated once here. The office reads and writes it: `parse` accepts a
77	    /// claimant's name by matching it against these, and a notice the office sends
78	    /// back cites the item type by the same name.
79	    fn name(self) -> &'static str {
80	        match self {
81	            Self::Sword => "sword",
82	            Self::Amulet => "amulet",
83	            Self::Staff => "staff",
84	            Self::Potion => "potion",
85	            Self::Rune => "rune",
86	            Self::Moonstone => "moonstone",
87	        }
88	    }
89	
90	    /// The item type the MHPCO recognises under this name, or a refusal: the
91	    /// office insures only the types on its price list, so a name it does not
92	    /// call any of them by names nothing it insures.
93	    pub fn parse(name: &str) -> Result<Self, String> {
94	        Self::INSURED
95	            .into_iter()
96	            .find(|insured| insured.name() == name)
97	            .ok_or_else(|| format!("the MHPCO does not insure items of type '{name}'"))
98	    }
99	}
100	
101	#[derive(Clone)]
102	pub struct Item {
103	    item_type: ItemType,
104	    cursed: bool,
105	    enchantment: u32,
106	    material: String,
107	}
108	
109	impl Item {
110	    pub fn new(item_type: ItemType) -> Self {
111	        Self {
112	            item_type,
113	            cursed: false,
114	            enchantment: 0,
115	            material: String::new(),
116	        }
117	    }
118	
119	    /// The material the MHPCO recorded for this item.
120	    pub fn of_material(mut self, material: &str) -> Self {
121	        self.material = material.to_owned();
122	        self
123	    }
124	
125	    /// The item's enchantment level, as recorded by the MHPCO.
126	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
127	        self.enchantment = enchantment;
128	        self
129	    }
130	
131	    /// A cursed item carries the MHPCO's risk surcharge.
132	    pub fn cursed(mut self) -> Self {
133	        self.cursed = true;
134	        self
135	    }
136	
137	    /// The item-specific risk surcharges this item carries, charged against the
138	    /// item's own base premium rather than the policy total. A component carries
139	    /// none: the MHPCO records no curse, enchantment or material for one, so it
140	    /// is never an affected item.
141	    fn item_surcharge(&self) -> f64 {
142	        self.item_type
143	            .main_item_base_premium()
144	            .map_or(0.0, |item_base| item_base * self.risk_surcharge_rate())
145	    }
146	
147	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
148	    /// enchantment threshold when reimbursing damage, so this one is named for
149	    /// the premium it surcharges.
150	    fn is_highly_enchanted(&self) -> bool {
151	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
152	    }
153	
154	    /// The share of a damage amount the MHPCO reimburses for this item, under the
155	    /// reimbursement clauses it reads today. Only one clause reduces the share:
156	    /// damage to a very highly enchanted item is reimbursed at half. That
157	    /// enchantment threshold is a higher one than the threshold that surcharges
158	    /// the premium, and the MHPCO reads the two independently -- the level and the
159	    /// share, though, are the one clause, so they are read together here.
160	    ///
161	    /// The MHPCO's other reimbursement clause -- dragon material is reimbursed in
162	    /// full -- deliberately has no branch here. Full reimbursement is already what
163	    /// an item under no clause receives, and the half-reimbursement clause wins
164	    /// wherever both apply, so the dragon clause cannot move any share the MHPCO
165	    /// recognises. The material stays a recorded property of the item; give it a
166	    /// branch only when a clause makes it change a share.
167	    fn reimbursement_share(&self) -> f64 {
168	        if self.enchantment >= HALF_REIMBURSEMENT_LEVEL {
169	            HALF_REIMBURSEMENT
170	        } else {
171	            FULL_REIMBURSEMENT
172	        }
173	    }
174	
175	    /// Curse and high enchantment are independent risks; an item carrying both
176	    /// is surcharged for both.
177	    fn risk_surcharge_rate(&self) -> f64 {
178	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
179	        let enchantment = if self.is_highly_enchanted() {
180	            HIGH_ENCHANTMENT_SURCHARGE
181	        } else {
182	            0.0
183	        };
184	        curse + enchantment
185	    }
186	}
187	
188	const PROCESSING_FEE: u64 = 5;
189	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
190	/// Cursed items add a risk surcharge on their own base premium.
191	const CURSE_SURCHARGE: f64 = 0.50;
192	/// Long-standing customers -- 2 or more years of business with the MHPCO --
193	/// receive a loyalty discount on the policy base premium.
194	const LOYALTY_YEARS: u32 = 2;
195	const LOYALTY_DISCOUNT: f64 = 0.20;
196	/// Customers receive a discount on each contract after their first.
197	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
198	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
199	/// surcharge on their own base premium.
200	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
201	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
202	/// Components -- for example runes and moonstones -- share one price-list row.
203	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
204	
205	/// How the MHPCO settles a rated premium into the amount it bills: the rated
206	/// fraction is rounded in the MHPCO's own favour -- upwards, the larger amount
207	/// -- and the processing fee is added to every premium at the very end.
208	fn settled_premium(rated: f64) -> u64 {
209	    rated.ceil() as u64 + PROCESSING_FEE
210	}
211	
212	/// The policy-wide modifier rate, charged against the policy base premium --
213	/// the sum of all item base premiums. The MHPCO nets its policy-wide modifiers
214	/// against one another: a first insurance carries an initial assessment
215	/// surcharge, a long-standing customer earns a loyalty discount, and every
216	/// contract after the customer's first earns a follow-up discount.
217	fn policy_modifier_rate(customer: &Customer, contract: Contract) -> f64 {
218	    let loyalty = if customer.is_long_standing() {
219	        LOYALTY_DISCOUNT
220	    } else {
221	        0.0
222	    };
223	    let follow_up = match contract {
224	        Contract::First => 0.0,
225	        Contract::FollowUp => FOLLOW_UP_CONTRACT_DISCOUNT,
226	    };
227	    FIRST_INSURANCE_SURCHARGE - loyalty - follow_up
228	}
229	
230	/// A building block of exactly 3 alike components is offered at this price
231	/// instead of the per-component base premium.
232	const COMPONENT_BLOCK_SIZE: usize = 3;
233	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
234	
235	fn component_charge(alike_count: usize) -> f64 {
236	    if alike_count == COMPONENT_BLOCK_SIZE {
237	        COMPONENT_BLOCK_BASE_PREMIUM
238	    } else {
239	        alike_count as f64 * COMPONENT_BASE_PREMIUM
240	    }
241	}
242	
243	/// The policy's components gathered into groups of alike ones, each group
244	/// reported as its size. Alike components are the ones charged together, so the
245	/// MHPCO's reading of "alike" -- same item type -- lives here and nowhere else.
246	fn alike_component_groups(items: &[Item]) -> Vec<usize> {
247	    let mut groups: Vec<(ItemType, usize)> = Vec::new();
248	    for component in items.iter().filter(|item| item.item_type.is_component()) {
249	        match groups
250	            .iter_mut()
251	            .find(|(group_type, _)| *group_type == component.item_type)
252	        {
253	            Some((_, count)) => *count += 1,
254	            None => groups.push((component.item_type, 1)),
255	        }
256	    }
257	    groups.into_iter().map(|(_, count)| count).collect()
258	}
259	
260	/// Main items are charged one price-list row each, individually.
261	fn main_items_base_premium(items: &[Item]) -> f64 {
262	    items
263	        .iter()
264	        .filter_map(|item| item.item_type.main_item_base_premium())
265	        .sum()
266	}
267	
268	/// Components are charged per group of alike components, so that a group of
269	/// exactly 3 earns the block price.
270	fn component_blocks_base_premium(items: &[Item]) -> f64 {
271	    alike_component_groups(items)
272	        .into_iter()
273	        .map(component_charge)
274	        .sum()
275	}
276	
277	/// The policy base premium is the sum of the items' base premiums, with alike
278	/// components charged as blocks. This is an intermediate rating amount the MHPCO
279	/// works from, not an amount it quotes: it is unrounded and carries no
280	/// processing fee, so it stays inside the office. What the office publishes is
281	/// `quote`.
282	fn policy_base_premium(items: &[Item]) -> f64 {
283	    main_items_base_premium(items) + component_blocks_base_premium(items)
284	}
285	
286	/// Item-specific modifiers apply to the base premium of the affected item, not
287	/// to the policy total.
288	fn item_surcharges(items: &[Item]) -> f64 {
289	    items.iter().map(Item::item_surcharge).sum()
290	}
291	
292	/// A customer's first contract with the MHPCO, or any contract after it.
293	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
294	pub enum Contract {
295	    First,
296	    FollowUp,
297	}
298	
299	/// What the MHPCO rates this policy at, as an exact fraction: the policy base
300	/// premium, modified policy-wide for the customer and the contract, plus the
301	/// surcharges carried by the individual affected items. This is the rating
302	/// decision; it is deliberately unrounded and carries no processing fee.
303	fn rated_premium(customer: &Customer, items: &[Item], contract: Contract) -> f64 {
304	    let policy_base = policy_base_premium(items);
305	    policy_base + policy_base * policy_modifier_rate(customer, contract) + item_surcharges(items)
306	}
307	
308	/// The premium the customer is billed: the MHPCO rates the policy, then settles
309	/// the rated amount into the amount billed.
310	pub fn quote(customer: &Customer, items: &[Item], contract: Contract) -> u64 {
311	    settled_premium(rated_premium(customer, items, contract))
312	}
313	
314	/// Damage to an item enchanted at this level or above is reimbursed at half.
315	const HALF_REIMBURSEMENT_LEVEL: u32 = 8;
316	const HALF_REIMBURSEMENT: f64 = 0.50;
317	const FULL_REIMBURSEMENT: f64 = 1.0;
318	
319	/// Components are insured at this value each.
320	const COMPONENT_INSURANCE_VALUE: u64 = 250;
321	
322	/// The total payout per policy is capped at this multiple of its insurance sum.
323	const CAP_MULTIPLE: u64 = 2;
324	
325	/// A deductible applies per damage event, once for each damaged item.
326	const DEDUCTIBLE_PER_DAMAGE: f64 = 100.0;
327	
328	/// A single damaged item reported in an incident.
329	pub struct Damage {
330	    item_type: ItemType,
331	    amount: i64,
332	}
333	
334	impl Damage {
335	    pub fn new(item_type: ItemType, amount: i64) -> Self {
336	        Self { item_type, amount }
337	    }
338	
339	    /// The damages of one incident are all entertained, or the incident is
340	    /// refused whole: the MHPCO reads a damage report for admissibility before it
341	    /// asks which insured item answers, so an inadmissible report is refused on
342	    /// its own terms rather than as a coverage failure.
343	    fn check_all_reportable(damages: &[Self]) -> Result<(), String> {
344	        damages.iter().try_for_each(Self::check_reportable)
345	    }
346	
347	    /// The MHPCO does not entertain a damage report for a negative amount.
348	    fn check_reportable(&self) -> Result<(), String> {
349	        if self.amount < 0 {
350	            return Err(format!(
351	                "a damage to a {} cannot be a negative amount of {} G",
352	                self.item_type.name(),
353	                self.amount
354	            ));
355	        }
356	        Ok(())
357	    }
358	
359	    /// What the MHPCO reimburses for this one damaged item, as an exact
360	    /// fraction: the share of the damage amount the insured item's clauses
361	    /// allow, less the deductible that applies once per damage event.
362	    fn reimbursement(&self, insured: &Item) -> f64 {
363	        self.amount as f64 * insured.reimbursement_share() - DEDUCTIBLE_PER_DAMAGE
364	    }
365	}
366	
367	/// How the MHPCO settles a reimbursed amount into the amount it pays out: the
368	/// reimbursed fraction is rounded in the MHPCO's own favour -- downwards, the
369	/// smaller amount -- which is the opposite direction from a premium.
370	fn settled_payout(reimbursed: f64) -> u64 {
371	    reimbursed.floor() as u64
372	}
373	
374	/// What the MHPCO pays out on one claim.
375	#[derive(Debug, PartialEq, Eq)]
376	pub struct Settlement {
377	    pub payout: u64,
378	    pub remaining_cap: u64,
379	}
380	
381	/// A policy the MHPCO has written over a customer's items.
382	pub struct Policy {
383	    items: Vec<Item>,
384	    remaining_cap: u64,
385	}
386	
387	/// The MHPCO's record of which insured items have already answered for a damage
388	/// within one incident. The office holds each insured item to at most one damage
389	/// per incident, so an incident reporting more damaged items of a type than the
390	/// policy insures finds no further item to answer and is rejected whole.
391	///
392	/// The ledger is the MHPCO's coverage decision, kept apart from how a damage is
393	/// reimbursed once covered: which insured item answers may come to depend on the
394	/// item's own properties, while what it reimburses is already the clauses on
395	/// `Item` and `Damage`.
396	struct CoverageLedger {
397	    answered: Vec<usize>,
398	}
399	
400	impl CoverageLedger {
401	    /// A fresh ledger: no insured item has answered yet in this incident.
402	    fn for_incident() -> Self {
403	        Self {
404	            answered: Vec::new(),
405	        }
406	    }
407	
408	    /// The insured item that answers for this damage, recorded as answered so it
409	    /// cannot answer again in this incident. Any insured item of the reported type
410	    /// that has not yet answered will do: two items of a type carry the same
411	    /// reimbursement clauses, so which one is chosen cannot move the payout.
412	    fn assign(&mut self, policy: &Policy, damage: &Damage) -> Result<usize, String> {
413	        let index = policy
414	            .items
415	            .iter()
416	            .enumerate()
417	            .position(|(index, item)| {
418	                item.item_type == damage.item_type && !self.answered.contains(&index)
419	            })
420	            .ok_or_else(|| {
421	                format!(
422	                    "the policy covers no unclaimed item of type '{}'",
423	                    damage.item_type.name()
424	                )
425	            })?;
426	        self.answered.push(index);
427	        Ok(index)
428	    }
429	}
430	
431	impl Policy {
432	    pub fn new(items: &[Item]) -> Self {
433	        Self {
434	            remaining_cap: Self::payout_cap(items),
435	            items: items.to_vec(),
436	        }
437	    }
438	
439	    /// The policy's insurance sum: the sum of the insured items' insurance
440	    /// values. Every insured item counts its own value, so two items of one type
441	    /// count twice, and a block of alike components counts each component -- the
442	    /// block discount is a premium offer and leaves the insurance sum untouched.
443	    fn insurance_sum(items: &[Item]) -> u64 {
444	        items
445	            .iter()
446	            .map(|item| item.item_type.insurance_value())
447	            .sum()
448	    }
449	
450	    /// What the MHPCO will pay out over the whole life of this policy. The cap is
451	    /// read off the insurance sum alone: premium modifiers rate the contract and
452	    /// do not raise the cap.
453	    fn payout_cap(items: &[Item]) -> u64 {
454	        CAP_MULTIPLE * Self::insurance_sum(items)
455	    }
456	
457	    /// The insured items that answer for the damages of one incident, in the
458	    /// order the damages were reported. Assigning coverage for the whole
459	    /// incident at once is what lets the MHPCO hold each insured item to at most
460	    /// one damage, and so notice an incident that over-reports a type.
461	    fn covering_items(&self, damages: &[Damage]) -> Result<Vec<&Item>, String> {
462	        let mut ledger = CoverageLedger::for_incident();
463	        damages
464	            .iter()
465	            .map(|damage| ledger.assign(self, damage).map(|index| &self.items[index]))
466	            .collect()
467	    }
468	
469	    /// What the MHPCO reimburses for a whole incident, as an exact fraction: the
470	    /// office entertains the report, finds the insured item that answers for each
471	    /// damage, and reimburses each under that item's clauses. This is the
472	    /// incident-level amount the MHPCO recognises, before it is settled into the
473	    /// amount paid out.
474	    fn reimbursed_total(&self, damages: &[Damage]) -> Result<f64, String> {
475	        Damage::check_all_reportable(damages)?;
476	        let covering = self.covering_items(damages)?;
477	        Ok(damages
478	            .iter()
479	            .zip(covering)
480	            .map(|(damage, insured)| damage.reimbursement(insured))
481	            .sum())
482	    }
483	
484	    /// The MHPCO's cap clause, applied to one settled amount: the cap limits what
485	    /// the policy pays out over its whole life, so an amount the MHPCO would
486	    /// otherwise pay is reduced to whatever cap is left, and what it does pay
487	    /// draws the cap down. The clause reads the already-settled whole-G amount --
488	    /// the cap is stated in whole G and limits the payout, not the reimbursement
489	    /// behind it.
490	    fn pay_within_cap(&mut self, settled: u64) -> u64 {
491	        let payout = settled.min(self.remaining_cap);
492	        self.remaining_cap -= payout;
493	        payout
494	    }
495	
496	    /// The MHPCO settles an incident against this policy: it reimburses the
497	    /// incident under the policy's clauses, settles that total into whole G, and
498	    /// pays it out so far as the policy's cap still allows.
499	    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
500	        let reimbursed = self.reimbursed_total(damages)?;
501	        let payout = self.pay_within_cap(settled_payout(reimbursed));
502	        Ok(Settlement {
503	            payout,
504	            remaining_cap: self.remaining_cap,
505	        })
506	    }
507	}
508	
509	/// One operation the MHPCO performs in a scenario.
510	pub enum Step {
511	    Quote { items: Vec<Item> },
512	    Claim { policy: usize, damages: Vec<Damage> },
513	}
514	
515	/// The MHPCO handles one customer's operations in the order they are brought.
516	pub struct Scenario {
517	    pub customer: Customer,
518	    pub steps: Vec<Step>,
519	}
520	
521	/// What the MHPCO records for one handled step.
522	#[derive(Debug, PartialEq, Eq)]
523	pub enum StepResult {
524	    Quote { premium: u64 },
525	    Claim { payout: u64, remaining_cap: u64 },
526	}
527	
528	/// The sequence of contracts the MHPCO has written for a customer so far: the
529	/// first quote is a first contract, every later one a follow-up.
530	struct ContractSequence {
531	    quotes_handled: usize,
532	}
533	
534	impl ContractSequence {
535	    fn opened() -> Self {
536	        Self { quotes_handled: 0 }
537	    }
538	
539	    fn next_contract(&mut self) -> Contract {
540	        let contract = if self.quotes_handled == 0 {
541	            Contract::First
542	        } else {
543	            Contract::FollowUp
544	        };
545	        self.quotes_handled += 1;
546	        contract
547	    }
548	}
549	
550	/// The policies the MHPCO's quotes have opened, addressed by the step that
551	/// quoted them. Every handled step takes a place in the register, whether or not
552	/// it opened a policy, because a claim names the policy it settles against by
553	/// that step's number.
554	struct PolicyRegister {
555	    by_step: Vec<Option<Policy>>,
556	}
557	
558	impl PolicyRegister {
559	    /// A fresh register: the MHPCO has handled no step of this scenario yet.
560	    fn none_yet() -> Self {
561	        Self { by_step: Vec::new() }
562	    }
563	
564	    /// The MHPCO records the policy this quote opened against the step that
565	    /// quoted it.
566	    fn record_quote(&mut self, items: &[Item]) {
567	        self.by_step.push(Some(Policy::new(items)));
568	    }
569	
570	    /// The MHPCO records a handled step that opened no policy, so that later
571	    /// steps are still numbered by their place in the scenario.
572	    fn record_no_policy(&mut self) {
573	        self.by_step.push(None);
574	    }
575	
576	    /// The policy the MHPCO will settle a claim against, or a refusal. A claim
577	    /// reaches backwards only: the office honours a reference to a policy one of
578	    /// its *earlier* quotes opened, so a step naming itself, a later step, or a
579	    /// step that quoted nothing names no policy it can settle against. The
580	    /// register holds exactly the steps already handled when the claim is read,
581	    /// which is what makes "earlier" the same question as "on the register".
582	    fn policy_quoted_at(&mut self, step: usize) -> Result<&mut Policy, String> {
583	        self.by_step
584	            .get_mut(step)
585	            .and_then(Option::as_mut)
586	            .ok_or_else(|| format!("step {step} did not open a policy"))
587	    }
588	}
589	
590	/// The MHPCO handles each step of a scenario in turn, keeping the policies its
591	/// quotes opened so that later claims can be settled against them.
592	pub fn run_scenario(scenario: &Scenario) -> Result<Vec<StepResult>, String> {
593	    let mut policies = PolicyRegister::none_yet();
594	    let mut contracts = ContractSequence::opened();
595	    let mut results = Vec::new();
596	
597	    for step in &scenario.steps {
598	        results.push(match step {
599	            Step::Quote { items } => {
600	                let premium = quote(&scenario.customer, items, contracts.next_contract());
601	                policies.record_quote(items);
602	                StepResult::Quote { premium }
603	            }
604	            Step::Claim { policy, damages } => {
605	                policies.record_no_policy();
606	                let settlement = policies.policy_quoted_at(*policy)?.claim(damages)?;
607	                StepResult::Claim {
608	                    payout: settlement.payout,
609	                    remaining_cap: settlement.remaining_cap,
610	                }
611	            }
612	        });
613	    }
614	
615	    Ok(results)
616	}
