    /// The MHPCO records a handled step that opened no policy, so that later
    /// steps are still numbered by their place in the scenario.
    fn record_no_policy(&mut self) {
        self.by_step.push(None);
    }

    /// The policy the MHPCO will settle a claim against, or a refusal. A claim
    /// reaches backwards only: the office honours a reference to a policy one of
    /// its *earlier* quotes opened, so a step naming itself, a later step, or a
    /// step that quoted nothing names no policy it can settle against. The
    /// register holds exactly the steps already handled when the claim is read,
    /// which is what makes "earlier" the same question as "on the register".
    fn policy_quoted_at(&mut self, step: usize) -> Result<&mut Policy, String> {
        self.by_step
            .get_mut(step)
            .and_then(Option::as_mut)
            .ok_or_else(|| format!("step {step} did not open a policy"))
    }
}

